with open("src/semver/version.py", "r") as f:
    content = f.read()

# m2: bump_build - add .0 append logic for non-numeric segments
# Keep the duplicate structure, just fix the first _increment_string call
old_m2 = """        cls = type(self)
        if self._build is not None:
            build = self._build
        elif token == "":
            build = "0"
        elif token is None:
            build = "build.0"
        else:
            build = str(token) + ".0"

        # self._build or (token or "build") + ".0"
        build = cls._increment_string(build)
        if self._build is not None:
            build = self._build
        elif token == "":
            build = "0"
        elif token is None:
            build = "build.0"
        else:
            build = str(token) + ".0"

        # self._build or (token or "build") + ".0"
        build = cls._increment_string(build)
        return cls(self._major, self._minor, self._patch, self._prerelease, build)"""

new_m2 = """        cls = type(self)
        if self._build is not None:
            build = self._build
            # Check if the last dot-separated segment is purely numeric
            last_segment = build.rsplit(".", 1)[-1]
            if last_segment.isdigit():
                build = cls._increment_string(build)
            else:
                # Try _increment_string; if it doesn't change anything, append .0
                new_build = cls._increment_string(build)
                if new_build != build:
                    build = new_build
                else:
                    build = build + ".0"
            return cls(self._major, self._minor, self._patch, self._prerelease, build)
        elif token == "":
            build = "0"
        elif token is None:
            build = "build.0"
        else:
            build = str(token) + ".0"

        # self._build or (token or "build") + ".0"
        build = cls._increment_string(build)
        if self._build is not None:
            build = self._build
        elif token == "":
            build = "0"
        elif token is None:
            build = "build.0"
        else:
            build = str(token) + ".0"

        # self._build or (token or "build") + ".0"
        build = cls._increment_string(build)
        return cls(self._major, self._minor, self._patch, self._prerelease, build)"""

if old_m2 in content:
    content = content.replace(old_m2, new_m2, 1)
    print("m2 applied")
else:
    print("ERROR: m2 old block not found")
